// Pseudo-logika w aplikacji Spring Boot (pelna implementacja w lekcji 4):
// 1. SPRAWDZ Redis: GET user:42
// 2. JESLI istnieje (cache hit) -> zwroc WPROST z Redis, PROMIN zapytanie do bazy
// 3. JESLI NIE istnieje (cache miss) -> zapytaj baze danych (PostgreSQL/RDS)
// 4. ZAPISZ wynik w Redis (SET user:42 ... + EXPIRE), na przyszlosc
// 5. Zwroc wynik do klienta

// BLEDNIE: JEDYNA kopia waznych danych finansowych TYLKO w Redis
SET saldo:user42 "1500.00"
// bez ZADNEGO odpowiadajacego wpisu w relacyjnej bazie danych -
// restart/awaria Redis (bez dodatkowej konfiguracji trwalosci) OZNACZA
// CALKOWITA, NIEODWRACALNA utrate tej informacji

// POPRAWNIE: PRAWDZIWE saldo zapisane w RDS/PostgreSQL (zrodlo prawdy)
// UPDATE konta SET saldo = 1500.00 WHERE user_id = 42;

// Redis JEDYNIE PRZYSPIESZA odczyt (cache), z krotkim czasem zycia:
SET saldo:user42 "1500.00" EX 300   # wygasa po 5 minutach, ZAWSZE mozna
                                      // odtworzyc z relacyjnej bazy danych
